// 基础 GET 请求
// app/api/posts/route.ts
import { NextResponse } from 'next/server'

// 导出对应 HTTP 方法的函数
export async function GET() {
  const posts = [
    { id: 1, title: '第一篇文章' },
    { id: 2, title: '第二篇文章' },
  ]

  // 返回 JSON 响应
  return NextResponse.json(posts)
}

